import { notebookSlotPages } from './notebook-model.mjs';

export async function mountCharacterSlots(container, { snapshot, assets, resolveFile, mountCharacter, unloadCharacter, onClose = () => {} }) {
  const doc=container.ownerDocument, win=doc.defaultView;
  const root=doc.createElement('section'); root.className='cs-window';root.setAttribute('role','dialog');root.setAttribute('aria-label','人物卡槽');
  const style=doc.createElement('style');style.textContent=`.cs-window{position:absolute;inset:0;background:#15110ceb;overflow:hidden;color:#eddbb6;font-family:"Songti SC",serif}.cs-window *{box-sizing:border-box}.cs-stage{position:absolute;width:1080px;height:600px;transform-origin:top left;padding:35px 40px;background:linear-gradient(125deg,#49392a,#281e16);border:1px solid #947452;border-radius:12px;box-shadow:0 18px 80px #0008}.cs-stage header{display:flex;align-items:center;gap:32px;height:58px}.cs-stage h2{font-size:30px;font-weight:500;margin:0}.cs-stage button{font:24px "Songti SC",serif;color:inherit;border:0;background:none;cursor:pointer}.cs-stage button:disabled{opacity:.35;cursor:default}.cs-close{margin-left:auto;min-width:72px;height:72px}.cs-stage input{font:23px "Songti SC",serif;padding:10px 15px;background:#eadbc0;color:#4e3a24;border:0;width:280px;border-radius:3px}.cs-people{position:absolute;left:40px;top:128px;width:310px;height:416px;overflow-y:auto;scrollbar-width:thin;display:grid;grid-template-columns:repeat(2,1fr);gap:10px;align-content:start;padding-right:10px}.cs-person{height:112px;border:1px solid #94775255!important;background:#ceb28012!important;border-radius:6px}.cs-person img{display:block;margin:auto;width:64px;height:64px;object-fit:contain}.cs-person span{display:block;font-size:23px;overflow:hidden;white-space:nowrap}.cs-person[aria-pressed=true]{border-color:#c9aa7c!important;background:#c2a57935!important}.cs-pockets{position:absolute;left:390px;top:163px;width:643px;height:306px;display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.cs-pocket{border:1px dashed #ab8b625c!important;border-radius:9px;background:#100c0830!important;box-shadow:inset 0 3px 13px #09070550}.cs-pocket img{width:83px;height:83px;display:block;margin:auto;object-fit:contain}.cs-pocket span{display:block;font-size:23px}.cs-pocket.empty{font-size:40px;color:#9b815f}.cs-total{position:absolute;left:390px;top:118px;font-size:22px;color:#bea47c}.cs-paging{position:absolute;left:560px;top:494px;display:flex;align-items:center;gap:55px;font:23px Georgia,serif}.cs-paging button{width:72px;height:72px}.cs-error{position:absolute;left:390px;bottom:16px;width:643px;font-size:22px;color:#e7bbaa}.cs-stage button:focus-visible,.cs-stage input:focus-visible{outline:2px solid #d4b67f;outline-offset:3px}`;
  root.innerHTML='<div class="cs-stage"><header><h2>人物卡槽</h2><input type="search" aria-label="搜索可加入卡槽的人物" placeholder="搜索人物"><button class="cs-close" aria-label="关闭卡槽">×</button></header><div class="cs-people" aria-label="可加入的人物"></div><div class="cs-total"></div><div class="cs-pockets" aria-label="当前卡槽"></div><div class="cs-paging"><button data-dir="-1" aria-label="上组卡槽">‹</button><span></span><button data-dir="1" aria-label="下组卡槽">›</button></div><div class="cs-error" role="status"></div></div>';
  root.prepend(style);container.append(root);let data=await snapshot(),page=0,query='',busy=false;
  const stage=root.querySelector('.cs-stage'), error=root.querySelector('.cs-error');
  function fit(){const scale=Math.min(container.clientWidth/1120,container.clientHeight/640);stage.style.transform=`scale(${scale})`;stage.style.left=`${(container.clientWidth-1080*scale)/2}px`;stage.style.top=`${(container.clientHeight-600*scale)/2}px`;}
  function face(button,actor){const asset=assets.characters.find(x=>x.id===actor.id||x.name===actor.name);if(actor.headUrl||asset?.head){const img=doc.createElement('img');img.src=actor.headUrl??resolveFile(asset.head);img.alt=actor.name;button.append(img);}const label=doc.createElement('span');label.textContent=actor.name;button.append(label);}
  async function transact(work){if(busy)return;busy=true;error.textContent='';try{await work();data=await snapshot();render();}catch(e){error.textContent=e.message;}finally{busy=false;}}
  function render(){
    const people=root.querySelector('.cs-people');people.replaceChildren();
    for(const actor of data.characters.filter(x=>x.slotEligible!==false&&!x.scoutingPending&&(!query||[x.name,...(x.aliases??[])].some(v=>v.toLocaleLowerCase().includes(query.toLocaleLowerCase()))))){const button=doc.createElement('button');button.className='cs-person';button.type='button';button.setAttribute('aria-label',`${actor.mounted?'移出':'加入'}卡槽：${actor.name}`);button.setAttribute('aria-pressed',String(actor.mounted));face(button,actor);button.draggable=true;button.addEventListener('dragstart',e=>e.dataTransfer.setData('application/x-hypnoos-character',actor.id));button.addEventListener('click',()=>void transact(()=>actor.mounted?unloadCharacter(data.slots.find(x=>x.ref.id===actor.id&&x.enabled!==false).slotId):mountCharacter(actor.id)));people.append(button);}
    const slots=notebookSlotPages(data.slots,page);page=slots.index;const pockets=root.querySelector('.cs-pockets');pockets.replaceChildren();
    for(let i=0;i<6;i++){const slot=slots.rows[i],actor=data.characters.find(x=>x.id===slot?.ref.id);const button=doc.createElement('button');button.type='button';button.className='cs-pocket'+(actor?'':' empty');button.setAttribute('aria-label',actor?`从卡槽移除${actor.name}`:'空卡槽');if(actor){face(button,actor);button.addEventListener('click',()=>void transact(()=>unloadCharacter(slot.slotId)));}else{button.textContent='＋';button.addEventListener('dragover',e=>e.preventDefault());button.addEventListener('drop',e=>{e.preventDefault();const id=e.dataTransfer.getData('application/x-hypnoos-character');if(id)void transact(()=>mountCharacter(id));});}pockets.append(button);}
    root.querySelector('.cs-total').textContent=`已装入 ${slots.total} 人`;
    root.querySelector('.cs-paging span').textContent=`${page+1} / ${slots.count}`;
    root.querySelector('[data-dir="-1"]').disabled=page===0;root.querySelector('[data-dir="1"]').disabled=page+1>=slots.count;
  }
  root.querySelector('input').addEventListener('input',e=>{query=e.target.value.trim();render();});root.querySelector('.cs-close').addEventListener('click',onClose);root.querySelectorAll('[data-dir]').forEach(button=>button.addEventListener('click',()=>{page+=Number(button.dataset.dir);render();}));
  root.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();onClose();}});
  fit();render();win.addEventListener('resize',fit);return{root,refresh:async()=>{data=await snapshot();render();},destroy(){win.removeEventListener('resize',fit);root.remove();}};
}
